/* Weeks 2 and 3 — same format as recipes.js. kind:"guide" = ordering guide, not a recipe. */
Object.assign(window.RECIPES, {
l8:{min:25,
 en:["Turkey meatballs in tomato sauce with rice",["200 g turkey mince (carne picada de pavo)","1 egg","2 tbsp oats or breadcrumbs","200 ml tomato sauce (tomate triturado)","50 g dry rice (≈150 g cooked)","1 tbsp olive oil","Garlic, parsley, salt","Salad"],["Mix the mince with the egg, oats, chopped garlic, parsley and salt. Shape 6–8 meatballs.","Brown them in the oil over medium-high heat for 5 minutes.","Add the tomato sauce, cover and simmer for 12 minutes.","Cook the rice meanwhile. Serve with the rice and a salad."]],
 es:["Albóndigas de pavo en salsa de tomate con arroz",["200 g de carne picada de pavo","1 huevo","2 cucharadas de avena o pan rallado","200 ml de tomate triturado","50 g de arroz en crudo (≈150 g cocido)","1 cucharada de aceite de oliva","Ajo, perejil, sal","Ensalada"],["Mezcla la carne con el huevo, la avena, el ajo picado, el perejil y la sal. Forma 6–8 albóndigas.","Dóralas en el aceite a fuego medio-alto 5 minutos.","Añade el tomate, tapa y cocina a fuego suave 12 minutos.","Cuece el arroz mientras tanto. Sirve con el arroz y una ensalada."]],
 ru:["Фрикадельки из индейки в томатном соусе с рисом",["200 г фарша индейки (carne picada de pavo)","1 яйцо","2 ст. ложки овсянки или панировочных сухарей","200 мл томатного соуса (tomate triturado)","50 г сухого риса (≈150 г варёного)","1 ст. ложка оливкового масла","Чеснок, петрушка, соль","Салат"],["Смешай фарш с яйцом, овсянкой, рубленым чесноком, петрушкой и солью. Слепи 6–8 фрикаделек.","Обжарь их в масле на среднем–сильном огне 5 минут.","Добавь томатный соус, накрой крышкой и туши 12 минут.","Тем временем свари рис. Подавай с рисом и салатом."]],
 hy:["Հնդկահավի կոլոլակ լոլիկի սոուսով և բրնձով",["200 գ հնդկահավի աղացած միս (carne picada de pavo)","1 ձու","2 ճաշի գդալ վարսակ կամ պաքսիմատ","200 մլ լոլիկի սոուս (tomate triturado)","50 գ չոր բրինձ (≈150 գ եփած)","1 ճաշի գդալ ձիթապտղի յուղ","Սխտոր, մաղադանոս, աղ","Աղցան"],["Աղացած միսը խառնիր ձվի, վարսակի, մանրացրած սխտորի, մաղադանոսի և աղի հետ։ Ձևավորիր 6–8 կոլոլակ։","Տապակիր յուղի մեջ միջին–ուժեղ կրակի վրա 5 րոպե։","Ավելացրու լոլիկի սոուսը, ծածկիր և թույլ կրակի վրա եփիր 12 րոպե։","Այդ ընթացքում եփիր բրինձը։ Մատուցիր բրնձով և աղցանով։"]]},
l9:{min:20,
 en:["Chicken fajita bowl",["200 g chicken breast, in strips","1 pepper, ½ onion","50 g dry rice (≈150 g cooked)","1 tbsp olive oil","Paprika (pimentón), cumin, salt","Lemon or lime"],["Cook the rice.","Sauté the sliced onion and pepper in half the oil for 5 minutes.","Add the chicken strips with the spices and the rest of the oil; cook 6–7 minutes until done.","Serve over the rice with a squeeze of lemon."]],
 es:["Bol de fajitas de pollo",["200 g de pechuga de pollo en tiras","1 pimiento, ½ cebolla","50 g de arroz en crudo (≈150 g cocido)","1 cucharada de aceite de oliva","Pimentón, comino, sal","Limón o lima"],["Cuece el arroz.","Saltea la cebolla y el pimiento en tiras con la mitad del aceite 5 minutos.","Añade el pollo con las especias y el resto del aceite; cocina 6–7 minutos hasta que esté hecho.","Sirve sobre el arroz con un chorrito de limón."]],
 ru:["Боул с курицей фахита",["200 г куриной грудки полосками","1 перец, ½ луковицы","50 г сухого риса (≈150 г варёного)","1 ст. ложка оливкового масла","Паприка (pimentón), кумин, соль","Лимон или лайм"],["Свари рис.","Обжарь нарезанные лук и перец в половине масла 5 минут.","Добавь курицу со специями и остатком масла; готовь 6–7 минут до готовности.","Выложи на рис и сбрызни лимоном."]],
 hy:["Հավի ֆահիտա ամանով",["200 գ հավի կրծքամիս՝ շերտերով","1 պղպեղ, ½ սոխ","50 գ չոր բրինձ (≈150 գ եփած)","1 ճաշի գդալ ձիթապտղի յուղ","Պապրիկա (pimentón), չաման, աղ","Կիտրոն կամ լայմ"],["Եփիր բրինձը։","Կտրատած սոխն ու պղպեղը տապակիր կես յուղով 5 րոպե։","Ավելացրու հավը համեմունքներով և մնացած յուղով, եփիր 6–7 րոպե՝ մինչև պատրաստ լինի։","Մատուցիր բրնձի վրա՝ կիտրոնի հյութով։"]]},
l10:{min:20,
 en:["Tuna pasta with tomato and courgette",["70 g dry whole-wheat pasta","2 cans of tuna in water","1 courgette (calabacín)","150 ml tomato sauce","1 garlic clove","1 tbsp olive oil","Oregano, salt"],["Boil the pasta in salted water (about 10 minutes).","Sauté the diced courgette and garlic in the oil for 6 minutes.","Add the tomato sauce and the drained tuna; heat for 2 minutes.","Drain the pasta, mix everything and add oregano."]],
 es:["Pasta con atún, tomate y calabacín",["70 g de pasta integral en crudo","2 latas de atún al natural","1 calabacín","150 ml de tomate triturado","1 diente de ajo","1 cucharada de aceite de oliva","Orégano, sal"],["Cuece la pasta en agua con sal (unos 10 minutos).","Saltea el calabacín en dados y el ajo con el aceite 6 minutos.","Añade el tomate y el atún escurrido; calienta 2 minutos.","Escurre la pasta, mezcla todo y añade orégano."]],
 ru:["Паста с тунцом, помидорами и кабачком",["70 г сухой цельнозерновой пасты","2 банки тунца в собственном соку","1 кабачок (calabacín)","150 мл томатного соуса","1 зубчик чеснока","1 ст. ложка оливкового масла","Орегано, соль"],["Свари пасту в подсоленной воде (около 10 минут).","Обжарь кубики кабачка с чесноком в масле 6 минут.","Добавь томатный соус и тунец без жидкости; прогрей 2 минуты.","Слей пасту, смешай всё и добавь орегано."]],
 hy:["Մակարոն տունայով, լոլիկով և դդմիկով",["70 գ չոր ամբողջահատիկ մակարոն","2 բանկա տունա սեփական հյութում","1 դդմիկ (calabacín)","150 մլ լոլիկի սոուս","1 պճեղ սխտոր","1 ճաշի գդալ ձիթապտղի յուղ","Օրեգանո, աղ"],["Մակարոնը եփիր աղաջրում (մոտ 10 րոպե)։","Խորանարդիկ կտրատած դդմիկն ու սխտորը տապակիր յուղով 6 րոպե։","Ավելացրու լոլիկի սոուսը և քամած տունան, տաքացրու 2 րոպե։","Քամիր մակարոնը, խառնիր ամեն ինչ և ավելացրու օրեգանո։"]]},
l11:{min:10,
 en:["Lentil salad with egg and tuna",["½ jar of cooked lentils, rinsed","1 can of tuna in water","1 boiled egg","1 tomato, ½ pepper, ¼ onion","1 tbsp olive oil, vinegar, salt","Parsley or cumin"],["Boil the egg for 10 minutes (or use one from the fridge).","Chop the tomato, pepper and onion small.","Mix the lentils, vegetables and drained tuna. Dress with oil, vinegar and salt.","Top with the egg in quarters. No cooking needed — great for taking to work."]],
 es:["Ensalada de lentejas con huevo y atún",["½ bote de lentejas cocidas, enjuagadas","1 lata de atún al natural","1 huevo cocido","1 tomate, ½ pimiento, ¼ de cebolla","1 cucharada de aceite de oliva, vinagre, sal","Perejil o comino"],["Cuece el huevo 10 minutos (o usa uno que tengas en la nevera).","Pica el tomate, el pimiento y la cebolla en trozos pequeños.","Mezcla las lentejas, las verduras y el atún escurrido. Aliña con aceite, vinagre y sal.","Pon el huevo en cuartos encima. No hay que cocinar: ideal para llevar al trabajo."]],
 ru:["Салат из чечевицы с яйцом и тунцом",["½ банки варёной чечевицы, промытой","1 банка тунца в собственном соку","1 варёное яйцо","1 помидор, ½ перца, ¼ луковицы","1 ст. ложка оливкового масла, уксус, соль","Петрушка или кумин"],["Свари яйцо 10 минут (или возьми готовое из холодильника).","Мелко нарежь помидор, перец и лук.","Смешай чечевицу, овощи и тунец без жидкости. Заправь маслом, уксусом и солью.","Сверху — яйцо четвертинками. Готовить не нужно: удобно брать на работу."]],
 hy:["Ոսպի աղցան ձվով և տունայով",["½ բանկա եփած ոսպ, լվացած","1 բանկա տունա սեփական հյութում","1 խաշած ձու","1 լոլիկ, ½ պղպեղ, ¼ սոխ","1 ճաշի գդալ ձիթապտղի յուղ, քացախ, աղ","Մաղադանոս կամ չաման"],["Ձուն եփիր 10 րոպե (կամ վերցրու պատրաստը սառնարանից)։","Լոլիկը, պղպեղն ու սոխը մանր կտրատիր։","Խառնիր ոսպը, բանջարեղենն ու քամած տունան։ Համեմիր յուղով, քացախով և աղով։","Վրան դիր քառորդ կտրատած ձուն։ Եփել պետք չէ. հարմար է աշխատանք տանելու համար։"]]},
l12:{min:15,
 en:["Chicken and vegetable stir-fry with rice",["200 g chicken breast, in strips","250 g frozen stir-fry vegetables","50 g dry rice (≈150 g cooked)","1 tbsp olive oil","1 tbsp soy sauce","1 garlic clove"],["Cook the rice.","Heat the oil in a wide pan until very hot. Cook the chicken strips for 5 minutes.","Add the frozen vegetables and garlic; stir-fry for 6 minutes.","Add the soy sauce, toss and serve over the rice."]],
 es:["Salteado de pollo y verduras con arroz",["200 g de pechuga de pollo en tiras","250 g de verduras congeladas para saltear","50 g de arroz en crudo (≈150 g cocido)","1 cucharada de aceite de oliva","1 cucharada de salsa de soja","1 diente de ajo"],["Cuece el arroz.","Calienta bien el aceite en una sartén grande. Haz el pollo 5 minutos.","Añade las verduras congeladas y el ajo; saltea 6 minutos.","Añade la salsa de soja, mezcla y sirve sobre el arroz."]],
 ru:["Стир-фрай из курицы с овощами и рисом",["200 г куриной грудки полосками","250 г замороженной овощной смеси","50 г сухого риса (≈150 г варёного)","1 ст. ложка оливкового масла","1 ст. ложка соевого соуса","1 зубчик чеснока"],["Свари рис.","Сильно разогрей масло в широкой сковороде. Обжарь курицу 5 минут.","Добавь замороженные овощи и чеснок; жарь, помешивая, 6 минут.","Добавь соевый соус, перемешай и подавай на рисе."]],
 hy:["Հավ և բանջարեղեն տապակով, բրնձով",["200 գ հավի կրծքամիս՝ շերտերով","250 գ սառեցված բանջարեղենի խառնուրդ","50 գ չոր բրինձ (≈150 գ եփած)","1 ճաշի գդալ ձիթապտղի յուղ","1 ճաշի գդալ սոյայի սոուս","1 պճեղ սխտոր"],["Եփիր բրինձը։","Լայն տապակում ուժեղ տաքացրու յուղը։ Հավը տապակիր 5 րոպե։","Ավելացրու սառեցված բանջարեղենն ու սխտորը, տապակիր խառնելով 6 րոպե։","Ավելացրու սոյայի սոուսը, խառնիր և մատուցիր բրնձի վրա։"]]},
l13:{min:40,
 en:["Fideuà — one plate, no seconds",["For 4 people:","300 g fideuà noodles (fideos)","400 g frozen seafood mix or peeled prawns","1 grated tomato, 2 garlic cloves","1 tsp sweet pimentón, saffron","3 tbsp olive oil","1 l fish stock (caldo de pescado)"],["Fry the noodles in the oil for 2 minutes until golden; take them out.","In the same pan, sauté the garlic, tomato and pimentón for 2 minutes. Add the seafood for 2 minutes.","Pour in the hot stock with the saffron. Add the noodles and cook 10 minutes without stirring.","Rest 3 minutes. One normal plate per person with a salad."]],
 es:["Fideuà: un plato, sin repetir",["Para 4 personas:","300 g de fideos para fideuà","400 g de preparado de marisco congelado o gambas peladas","1 tomate rallado, 2 dientes de ajo","1 cucharadita de pimentón dulce, azafrán","3 cucharadas de aceite de oliva","1 l de caldo de pescado"],["Fríe los fideos en el aceite 2 minutos hasta que se doren; sácalos.","En la misma paella, sofríe el ajo, el tomate y el pimentón 2 minutos. Añade el marisco 2 minutos.","Echa el caldo caliente con el azafrán. Añade los fideos y cocina 10 minutos sin remover.","Deja reposar 3 minutos. Un plato normal por persona con ensalada."]],
 ru:["Фидеуа — одна тарелка, без добавки",["На 4 человек:","300 г лапши для фидеуа (fideos)","400 г замороженной морской смеси или очищенных креветок","1 тёртый помидор, 2 зубчика чеснока","1 ч. л. сладкой паприки, шафран","3 ст. ложки оливкового масла","1 л рыбного бульона (caldo de pescado)"],["Обжарь лапшу в масле 2 минуты до золотистого цвета; вынь.","В той же сковороде обжарь чеснок, помидор и паприку 2 минуты. Добавь морепродукты на 2 минуты.","Влей горячий бульон с шафраном. Верни лапшу и готовь 10 минут, не помешивая.","Дай постоять 3 минуты. Одна обычная тарелка на человека с салатом."]],
 hy:["Ֆիդեուա — մեկ ափսե, առանց կրկնելու",["4 հոգու համար՝","300 գ ֆիդեուայի արիշտա (fideos)","400 գ սառեցված ծովամթերքի խառնուրդ կամ մաքրած ծովախեցգետին","1 քերած լոլիկ, 2 պճեղ սխտոր","1 թեյի գդալ քաղցր պապրիկա, զաֆրան","3 ճաշի գդալ ձիթապտղի յուղ","1 լ ձկան արգանակ (caldo de pescado)"],["Արիշտան տապակիր յուղի մեջ 2 րոպե՝ մինչև ոսկեգույն դառնա, հանիր։","Նույն տապակում 2 րոպե տապակիր սխտորը, լոլիկն ու պապրիկան։ Ավելացրու ծովամթերքը 2 րոպեով։","Լցրու տաք արգանակը զաֆրանով։ Ավելացրու արիշտան և եփիր 10 րոպե՝ առանց խառնելու։","Թող 3 րոպե հանգստանա։ Մեկ սովորական ափսե մեկ հոգուն՝ աղցանով։"]]},
l14:{min:45,
 en:["Baked chicken thighs with potato and peppers",["2 skinless chicken thighs (contramuslos, ≈250 g)","1 potato, 1 pepper, ½ onion","1 tbsp olive oil","Garlic, thyme or oregano, lemon, salt"],["Heat the oven to 200 °C. Slice the potato thin, the pepper in strips and the onion in rings. Spread on a tray with half the oil and salt.","Put the thighs on top. Season with salt, garlic, herbs and the rest of the oil.","Bake 35–40 minutes until the chicken is golden and the potato soft.","Finish with lemon. Serve with a salad."]],
 es:["Contramuslos al horno con patata y pimientos",["2 contramuslos de pollo sin piel (≈250 g)","1 patata, 1 pimiento, ½ cebolla","1 cucharada de aceite de oliva","Ajo, tomillo u orégano, limón, sal"],["Precalienta el horno a 200 °C. Corta la patata fina, el pimiento en tiras y la cebolla en aros. Extiéndelos en una bandeja con la mitad del aceite y sal.","Pon los contramuslos encima. Sazona con sal, ajo, hierbas y el resto del aceite.","Hornea 35–40 minutos, hasta que el pollo esté dorado y la patata tierna.","Termina con limón. Sirve con ensalada."]],
 ru:["Запечённые куриные бёдра с картофелем и перцем",["2 куриных бедра без кожи (contramuslos, ≈250 г)","1 картофелина, 1 перец, ½ луковицы","1 ст. ложка оливкового масла","Чеснок, тимьян или орегано, лимон, соль"],["Разогрей духовку до 200 °C. Нарежь картофель тонко, перец полосками, лук кольцами. Разложи на противне с половиной масла и солью.","Сверху положи бёдра. Приправь солью, чесноком, травами и остатком масла.","Запекай 35–40 минут, пока курица не подрумянится, а картофель не станет мягким.","Сбрызни лимоном. Подавай с салатом."]],
 hy:["Ջեռոցում թխած հավի ազդրեր կարտոֆիլով և պղպեղով",["2 հավի ազդր առանց մաշկի (contramuslos, ≈250 գ)","1 կարտոֆիլ, 1 պղպեղ, ½ սոխ","1 ճաշի գդալ ձիթապտղի յուղ","Սխտոր, ուրց կամ օրեգանո, կիտրոն, աղ"],["Ջեռոցը տաքացրու 200 °C։ Կարտոֆիլը կտրատիր բարակ, պղպեղը՝ շերտերով, սոխը՝ օղակներով։ Փռիր սկուտեղին կես յուղով և աղով։","Վրան դիր ազդրերը։ Համեմիր աղով, սխտորով, կանաչիով և մնացած յուղով։","Թխիր 35–40 րոպե՝ մինչև հավը ոսկեգույն դառնա, իսկ կարտոֆիլը փափկի։","Վրան քամիր կիտրոն։ Մատուցիր աղցանով։"]]},
l15:{min:15,
 en:["Lemon chicken with couscous",["200 g chicken breast","50 g dry couscous (≈150 g cooked)","1 lemon","1 tbsp olive oil","Garlic, parsley, salt","Cucumber and tomato for the side"],["Pour 60 ml of boiling water over the couscous with a pinch of salt. Cover 5 minutes, then fluff with a fork.","Flatten the chicken, season with salt, garlic and lemon zest. Grill 4–5 minutes per side.","Squeeze the lemon over the chicken.","Serve with the couscous, chopped cucumber and tomato dressed with the oil."]],
 es:["Pollo al limón con cuscús",["200 g de pechuga de pollo","50 g de cuscús en crudo (≈150 g cocido)","1 limón","1 cucharada de aceite de oliva","Ajo, perejil, sal","Pepino y tomate para acompañar"],["Vierte 60 ml de agua hirviendo sobre el cuscús con una pizca de sal. Tapa 5 minutos y suelta con un tenedor.","Aplana el pollo y sazona con sal, ajo y ralladura de limón. Hazlo a la plancha 4–5 minutos por lado.","Exprime el limón sobre el pollo.","Sirve con el cuscús y el pepino y tomate troceados, aliñados con el aceite."]],
 ru:["Лимонная курица с кускусом",["200 г куриной грудки","50 г сухого кускуса (≈150 г готового)","1 лимон","1 ст. ложка оливкового масла","Чеснок, петрушка, соль","Огурец и помидор на гарнир"],["Залей кускус 60 мл кипятка со щепоткой соли. Накрой на 5 минут и разрыхли вилкой.","Отбей курицу, приправь солью, чесноком и лимонной цедрой. Жарь на гриле по 4–5 минут с каждой стороны.","Выжми лимон на курицу.","Подавай с кускусом и нарезанными огурцом и помидором, заправленными маслом."]],
 hy:["Կիտրոնով հավ քուսքուսով",["200 գ հավի կրծքամիս","50 գ չոր քուսքուս (≈150 գ պատրաստի)","1 կիտրոն","1 ճաշի գդալ ձիթապտղի յուղ","Սխտոր, մաղադանոս, աղ","Վարունգ և լոլիկ՝ կողքին"],["Քուսքուսի վրա լցրու 60 մլ եռացող ջուր մի պտղունց աղով։ Ծածկիր 5 րոպե, հետո պատառաքաղով փխրեցրու։","Հավը ծեծիր, համեմիր աղով, սխտորով և կիտրոնի կեղևով։ Տապակիր 4–5 րոպե յուրաքանչյուր կողմից։","Հավի վրա քամիր կիտրոնը։","Մատուցիր քուսքուսով և յուղով համեմված կտրատած վարունգով ու լոլիկով։"]]},
l16:{min:15,
 en:["Chicken and vegetable wrap",["1 whole-wheat wrap","150 g chicken breast, in strips","½ pepper, ¼ onion","Lettuce, tomato","1 tbsp Greek yogurt (as sauce)","1 tsp olive oil, paprika, salt"],["Cook the chicken strips with the pepper and onion in the oil for 7 minutes. Season with paprika and salt.","Warm the wrap 20 seconds in a dry pan.","Spread the yogurt, add lettuce, tomato and the chicken mix.","Roll it up tightly and cut in half. Add a side salad."]],
 es:["Wrap de pollo y verduras",["1 tortilla integral (wrap)","150 g de pechuga de pollo en tiras","½ pimiento, ¼ de cebolla","Lechuga, tomate","1 cucharada de yogur griego (como salsa)","1 cucharadita de aceite de oliva, pimentón, sal"],["Haz el pollo con el pimiento y la cebolla en el aceite 7 minutos. Sazona con pimentón y sal.","Calienta la tortilla 20 segundos en una sartén sin aceite.","Unta el yogur, añade lechuga, tomate y el pollo con las verduras.","Enróllalo bien apretado y córtalo por la mitad. Acompaña con ensalada."]],
 ru:["Ролл с курицей и овощами",["1 цельнозерновая лепёшка (wrap)","150 г куриной грудки полосками","½ перца, ¼ луковицы","Листья салата, помидор","1 ст. ложка греческого йогурта (как соус)","1 ч. л. оливкового масла, паприка, соль"],["Обжарь курицу с перцем и луком в масле 7 минут. Приправь паприкой и солью.","Прогрей лепёшку 20 секунд на сухой сковороде.","Намажь йогуртом, добавь салат, помидор и курицу с овощами.","Плотно сверни и разрежь пополам. Добавь салат на гарнир."]],
 hy:["Հավով և բանջարեղենով ռոլ",["1 ամբողջահատիկ լավաշ (wrap)","150 գ հավի կրծքամիս՝ շերտերով","½ պղպեղ, ¼ սոխ","Հազար, լոլիկ","1 ճաշի գդալ հունական յոգուրտ (որպես սոուս)","1 թեյի գդալ ձիթապտղի յուղ, պապրիկա, աղ"],["Հավը պղպեղի և սոխի հետ տապակիր յուղով 7 րոպե։ Համեմիր պապրիկայով և աղով։","Լավաշը 20 վայրկյան տաքացրու չոր տապակում։","Քսիր յոգուրտը, ավելացրու հազարը, լոլիկն ու հավը բանջարեղենով։","Ամուր փաթաթիր և կիսիր։ Կողքին՝ աղցան։"]]},
l17:{min:30,
 en:["Lean pork in tomato (magro con tomate) with rice",["200 g lean pork in cubes (magro de cerdo)","200 ml crushed tomato","½ onion, 1 garlic clove","1 tbsp olive oil","Paprika (pimentón), salt","50 g dry rice (≈150 g cooked)"],["Brown the pork in the oil over high heat for 5 minutes.","Add the chopped onion and garlic; cook 4 minutes.","Add the tomato and pimentón; simmer uncovered 15–20 minutes until thick.","Cook the rice meanwhile and serve together."]],
 es:["Magro con tomate y arroz",["200 g de magro de cerdo en dados","200 ml de tomate triturado","½ cebolla, 1 diente de ajo","1 cucharada de aceite de oliva","Pimentón, sal","50 g de arroz en crudo (≈150 g cocido)"],["Dora el magro en el aceite a fuego fuerte 5 minutos.","Añade la cebolla y el ajo picados; cocina 4 minutos.","Agrega el tomate y el pimentón; cocina destapado 15–20 minutos hasta que espese.","Cuece el arroz mientras tanto y sirve junto."]],
 ru:["Постная свинина в томате (magro con tomate) с рисом",["200 г постной свинины кубиками (magro de cerdo)","200 мл протёртых томатов","½ луковицы, 1 зубчик чеснока","1 ст. ложка оливкового масла","Паприка (pimentón), соль","50 г сухого риса (≈150 г варёного)"],["Обжарь свинину в масле на сильном огне 5 минут.","Добавь рубленые лук и чеснок; готовь 4 минуты.","Добавь томаты и паприку; туши без крышки 15–20 минут, пока соус не загустеет.","Тем временем свари рис и подавай вместе."]],
 hy:["Խոզի անյուղ միս լոլիկով (magro con tomate) և բրինձ",["200 գ խոզի անյուղ միս՝ խորանարդիկներով (magro de cerdo)","200 մլ տրորած լոլիկ","½ սոխ, 1 պճեղ սխտոր","1 ճաշի գդալ ձիթապտղի յուղ","Պապրիկա (pimentón), աղ","50 գ չոր բրինձ (≈150 գ եփած)"],["Միսը տապակիր յուղով ուժեղ կրակի վրա 5 րոպե։","Ավելացրու մանրացրած սոխն ու սխտորը, եփիր 4 րոպե։","Ավելացրու լոլիկն ու պապրիկան, եփիր առանց կափարիչի 15–20 րոպե՝ մինչև թանձրանա։","Այդ ընթացքում եփիր բրինձը և մատուցիր միասին։"]]},
l18:{min:20,
 en:["Pasta with chicken and broccoli",["70 g dry whole-wheat pasta","150 g chicken breast, diced","½ head of broccoli","1 garlic clove","1 tbsp olive oil","Chili flakes, lemon, salt"],["Boil the pasta. Add the broccoli florets to the same pot for the last 4 minutes.","Sauté the chicken with the garlic in the oil for 6 minutes.","Drain the pasta and broccoli and add them to the pan.","Toss with chili flakes and a squeeze of lemon."]],
 es:["Pasta con pollo y brócoli",["70 g de pasta integral en crudo","150 g de pechuga de pollo en dados","½ brócoli","1 diente de ajo","1 cucharada de aceite de oliva","Guindilla en copos, limón, sal"],["Cuece la pasta. Añade los ramilletes de brócoli a la misma olla los últimos 4 minutos.","Saltea el pollo con el ajo en el aceite 6 minutos.","Escurre la pasta y el brócoli y añádelos a la sartén.","Mezcla con la guindilla y un chorrito de limón."]],
 ru:["Паста с курицей и брокколи",["70 г сухой цельнозерновой пасты","150 г куриной грудки кубиками","½ кочана брокколи","1 зубчик чеснока","1 ст. ложка оливкового масла","Хлопья чили, лимон, соль"],["Свари пасту. За 4 минуты до готовности добавь в ту же кастрюлю соцветия брокколи.","Обжарь курицу с чесноком в масле 6 минут.","Слей пасту с брокколи и добавь в сковороду.","Перемешай с чили и сбрызни лимоном."]],
 hy:["Մակարոն հավով և բրոկոլիով",["70 գ չոր ամբողջահատիկ մակարոն","150 գ հավի կրծքամիս՝ խորանարդիկներով","½ գլուխ բրոկոլի","1 պճեղ սխտոր","1 ճաշի գդալ ձիթապտղի յուղ","Չիլիի փաթիլ, կիտրոն, աղ"],["Եփիր մակարոնը։ Վերջին 4 րոպեին նույն կաթսայի մեջ ավելացրու բրոկոլին։","Հավը սխտորի հետ տապակիր յուղով 6 րոպե։","Քամիր մակարոնն ու բրոկոլին և ավելացրու տապակ։","Խառնիր չիլիով և կիտրոնի հյութով։"]]},
l19:{min:20,
 en:["Grilled mackerel with potato and salad",["1 large or 2 small mackerel (caballa, ≈250 g), cleaned","1 potato","Salad","1 tbsp olive oil","Garlic, parsley, lemon, salt"],["Wash the potato, prick it and microwave 6–8 minutes until soft.","Dry the fish, salt it and grill on a very hot plancha 4 minutes per side.","Mix chopped garlic and parsley with the oil and pour it over the fish.","Serve with the potato, lemon and salad. Mackerel is cheap and full of omega-3."]],
 es:["Caballa a la plancha con patata y ensalada",["1 caballa grande o 2 pequeñas (≈250 g), limpias","1 patata","Ensalada","1 cucharada de aceite de oliva","Ajo, perejil, limón, sal"],["Lava la patata, pínchala y hazla en el microondas 6–8 minutos hasta que esté blanda.","Seca el pescado, sálalo y hazlo en la plancha muy caliente 4 minutos por lado.","Mezcla ajo y perejil picados con el aceite y échalo por encima.","Sirve con la patata, limón y ensalada. La caballa es barata y llena de omega-3."]],
 ru:["Скумбрия на гриле с картофелем и салатом",["1 большая или 2 маленькие скумбрии (caballa, ≈250 г), очищенные","1 картофелина","Салат","1 ст. ложка оливкового масла","Чеснок, петрушка, лимон, соль"],["Вымой картофель, наколи и готовь в микроволновке 6–8 минут до мягкости.","Обсуши рыбу, посоли и жарь на очень горячей plancha по 4 минуты с каждой стороны.","Смешай рубленые чеснок и петрушку с маслом и полей рыбу.","Подавай с картофелем, лимоном и салатом. Скумбрия дешёвая и богата омега-3."]],
 hy:["Գրիլ սկումբրիա կարտոֆիլով և աղցանով",["1 մեծ կամ 2 փոքր սկումբրիա (caballa, ≈250 գ), մաքրած","1 կարտոֆիլ","Աղցան","1 ճաշի գդալ ձիթապտղի յուղ","Սխտոր, մաղադանոս, կիտրոն, աղ"],["Լվա կարտոֆիլը, ծակծկիր և դիր միկրոալիքային վառարան 6–8 րոպե՝ մինչև փափկի։","Ձուկը չորացրու, աղ արա և տապակիր շատ տաք plancha-ի վրա 4 րոպե յուրաքանչյուր կողմից։","Մանրացրած սխտորն ու մաղադանոսը խառնիր յուղով և լցրու ձկան վրա։","Մատուցիր կարտոֆիլով, կիտրոնով և աղցանով։ Սկումբրիան էժան է և հարուստ օմեգա-3-ով։"]]},
l20:{min:40,
 en:["Arroz del senyoret (seafood rice) — one plate",["For 4 people:","300 g bomba or round rice","400 g peeled prawns and squid rings (frozen seafood mix)","1 grated tomato, 2 garlic cloves","1 tsp sweet pimentón, saffron","3 tbsp olive oil","900 ml fish stock"],["Sauté the seafood in the oil for 2 minutes and take it out.","Sauté the garlic, tomato and pimentón for 2 minutes. Add the rice and stir for 1 minute.","Pour in the hot stock with the saffron. Cook 10 minutes on high, then 8 on low. Put the seafood back for the last 5 minutes.","Rest 5 minutes. One normal plate per person with a salad — no seconds."]],
 es:["Arroz del senyoret: un plato",["Para 4 personas:","300 g de arroz bomba o redondo","400 g de gambas peladas y anillas de calamar (preparado congelado)","1 tomate rallado, 2 dientes de ajo","1 cucharadita de pimentón dulce, azafrán","3 cucharadas de aceite de oliva","900 ml de caldo de pescado"],["Saltea el marisco en el aceite 2 minutos y sácalo.","Sofríe el ajo, el tomate y el pimentón 2 minutos. Añade el arroz y remueve 1 minuto.","Echa el caldo caliente con el azafrán. Cocina 10 minutos a fuego fuerte y 8 a fuego suave. Vuelve a poner el marisco los últimos 5 minutos.","Deja reposar 5 minutos. Un plato normal por persona con ensalada, sin repetir."]],
 ru:["Arroz del senyoret (рис с морепродуктами) — одна тарелка",["На 4 человек:","300 г риса бомба или круглого","400 г очищенных креветок и колец кальмара (замороженная смесь)","1 тёртый помидор, 2 зубчика чеснока","1 ч. л. сладкой паприки, шафран","3 ст. ложки оливкового масла","900 мл рыбного бульона"],["Обжарь морепродукты в масле 2 минуты и вынь.","Обжарь чеснок, помидор и паприку 2 минуты. Добавь рис и помешивай 1 минуту.","Влей горячий бульон с шафраном. Готовь 10 минут на сильном огне, затем 8 на слабом. Верни морепродукты за 5 минут до конца.","Дай постоять 5 минут. Одна обычная тарелка на человека с салатом, без добавки."]],
 hy:["Arroz del senyoret (ծովամթերքով բրինձ) — մեկ ափսե",["4 հոգու համար՝","300 գ bomba կամ կլոր բրինձ","400 գ մաքրած ծովախեցգետին և կաղամարի օղակներ (սառեցված խառնուրդ)","1 քերած լոլիկ, 2 պճեղ սխտոր","1 թեյի գդալ քաղցր պապրիկա, զաֆրան","3 ճաշի գդալ ձիթապտղի յուղ","900 մլ ձկան արգանակ"],["Ծովամթերքը տապակիր յուղով 2 րոպե և հանիր։","Տապակիր սխտորը, լոլիկն ու պապրիկան 2 րոպե։ Ավելացրու բրինձը և խառնիր 1 րոպե։","Լցրու տաք արգանակը զաֆրանով։ Եփիր 10 րոպե ուժեղ կրակի վրա, հետո 8 րոպե թույլ։ Վերջին 5 րոպեին վերադարձրու ծովամթերքը։","Թող 5 րոպե հանգստանա։ Մեկ սովորական ափսե մեկ հոգուն՝ աղցանով, առանց կրկնելու։"]]},
l21:{min:60,
 en:["Beef and vegetable stew with potato",["200 g stewing beef (ternera para guisar)","1 potato, 1 carrot, ½ onion, 1 garlic clove","100 ml crushed tomato","1 tbsp olive oil","Bay leaf, paprika (pimentón), salt","300 ml water or stock"],["Brown the beef in the oil for 5 minutes.","Add the chopped onion, carrot and garlic; cook 5 minutes.","Add the tomato, pimentón, bay leaf and water. Cover and simmer 40 minutes.","Add the potato in chunks for the last 20 minutes. Serve with a salad. Makes 2 portions — keep one for another day."]],
 es:["Ternera guisada con verduras y patata",["200 g de ternera para guisar","1 patata, 1 zanahoria, ½ cebolla, 1 diente de ajo","100 ml de tomate triturado","1 cucharada de aceite de oliva","Laurel, pimentón, sal","300 ml de agua o caldo"],["Dora la ternera en el aceite 5 minutos.","Añade la cebolla, la zanahoria y el ajo picados; cocina 5 minutos.","Agrega el tomate, el pimentón, el laurel y el agua. Tapa y cocina a fuego suave 40 minutos.","Añade la patata en trozos los últimos 20 minutos. Sirve con ensalada. Salen 2 raciones: guarda una para otro día."]],
 ru:["Тушёная говядина с овощами и картофелем",["200 г говядины для тушения (ternera para guisar)","1 картофелина, 1 морковь, ½ луковицы, 1 зубчик чеснока","100 мл протёртых томатов","1 ст. ложка оливкового масла","Лавровый лист, паприка (pimentón), соль","300 мл воды или бульона"],["Обжарь говядину в масле 5 минут.","Добавь нарезанные лук, морковь и чеснок; готовь 5 минут.","Добавь томаты, паприку, лавровый лист и воду. Накрой и туши 40 минут.","За 20 минут до конца добавь картофель кусочками. Подавай с салатом. Получается 2 порции — одну оставь на другой день."]],
 hy:["Շոգեխաշած տավարի միս բանջարեղենով և կարտոֆիլով",["200 գ տավարի միս շոգեխաշելու համար (ternera para guisar)","1 կարտոֆիլ, 1 գազար, ½ սոխ, 1 պճեղ սխտոր","100 մլ տրորած լոլիկ","1 ճաշի գդալ ձիթապտղի յուղ","Դափնու տերև, պապրիկա (pimentón), աղ","300 մլ ջուր կամ արգանակ"],["Միսը տապակիր յուղով 5 րոպե։","Ավելացրու կտրատած սոխը, գազարն ու սխտորը, եփիր 5 րոպե։","Ավելացրու լոլիկը, պապրիկան, դափնու տերևն ու ջուրը։ Ծածկիր և թույլ կրակի վրա եփիր 40 րոպե։","Վերջին 20 րոպեին ավելացրու կտորներով կտրատած կարտոֆիլը։ Մատուցիր աղցանով։ Ստացվում է 2 բաժին՝ մեկը պահիր մեկ այլ օրվա համար։"]]},
d8:{min:10,
 en:["Pisto with 2 poached eggs",["½ jar of pisto (≈200 g, Spanish ratatouille)","2 eggs","Salt, pepper","1 slice of bread (optional)"],["Heat the pisto in a small pan over medium heat.","Make two wells, crack an egg into each, cover and cook 4–5 minutes until the whites are set.","Season and eat straight from the pan."]],
 es:["Pisto con 2 huevos",["½ bote de pisto (≈200 g)","2 huevos","Sal, pimienta","1 rebanada de pan (opcional)"],["Calienta el pisto en una sartén pequeña a fuego medio.","Haz dos huecos, casca un huevo en cada uno, tapa y cocina 4–5 minutos hasta que la clara cuaje.","Salpimienta y come directamente de la sartén."]],
 ru:["Писто с 2 яйцами",["½ банки писто (≈200 г, испанское овощное рагу)","2 яйца","Соль, перец","1 ломтик хлеба (по желанию)"],["Разогрей писто в маленькой сковороде на среднем огне.","Сделай две ямки, разбей в каждую по яйцу, накрой крышкой и готовь 4–5 минут, пока белок не схватится.","Посоли, поперчи и ешь прямо из сковороды."]],
 hy:["Պիստո 2 ձվով",["½ բանկա պիստո (≈200 գ, իսպանական բանջարեղենային ռագու)","2 ձու","Աղ, պղպեղ","1 շերտ հաց (ըստ ցանկության)"],["Պիստոն տաքացրու փոքր տապակում միջին կրակի վրա։","Երկու փոս արա, յուրաքանչյուրի մեջ կոտրիր մեկ ձու, ծածկիր և եփիր 4–5 րոպե՝ մինչև սպիտակուցը պնդանա։","Աղ ու պղպեղ ավելացրու և կեր ուղիղ տապակից։"]]},
d9:{min:25,
 en:["Baked dorada with asparagus",["1 sea bream (dorada, ≈350 g), cleaned","1 bunch of green asparagus","1 lemon, 2 garlic cloves","1 tbsp olive oil","Salt, parsley"],["Heat the oven to 200 °C. Put the fish on a tray with lemon slices inside, sliced garlic, half the oil and salt.","Place the asparagus around it with the rest of the oil.","Bake 18–20 minutes until the flesh comes off the bone easily.","Finish with parsley and lemon."]],
 es:["Dorada al horno con espárragos",["1 dorada (≈350 g), limpia","1 manojo de espárragos verdes","1 limón, 2 dientes de ajo","1 cucharada de aceite de oliva","Sal, perejil"],["Precalienta el horno a 200 °C. Pon la dorada en una bandeja con rodajas de limón dentro, ajo laminado, la mitad del aceite y sal.","Coloca los espárragos alrededor con el resto del aceite.","Hornea 18–20 minutos, hasta que la carne se separe fácilmente de la espina.","Termina con perejil y limón."]],
 ru:["Запечённая дорада со спаржей",["1 дорада (≈350 г), очищенная","1 пучок зелёной спаржи","1 лимон, 2 зубчика чеснока","1 ст. ложка оливкового масла","Соль, петрушка"],["Разогрей духовку до 200 °C. Положи рыбу на противень, внутрь — ломтики лимона, сверху нарезанный чеснок, половину масла и соль.","Вокруг разложи спаржу с остатком масла.","Запекай 18–20 минут, пока мясо не станет легко отделяться от кости.","Посыпь петрушкой и сбрызни лимоном."]],
 hy:["Ջեռոցում թխած դորադա ծնեբեկով",["1 դորադա (≈350 գ), մաքրած","1 կապ կանաչ ծնեբեկ","1 կիտրոն, 2 պճեղ սխտոր","1 ճաշի գդալ ձիթապտղի յուղ","Աղ, մաղադանոս"],["Ջեռոցը տաքացրու 200 °C։ Ձուկը դիր սկուտեղին, ներսում՝ կիտրոնի շերտեր, վրան՝ կտրատած սխտոր, կես յուղ և աղ։","Շուրջը դիր ծնեբեկը մնացած յուղով։","Թխիր 18–20 րոպե՝ մինչև միսը հեշտությամբ անջատվի ոսկորից։","Վրան՝ մաղադանոս և կիտրոն։"]]},
d10:{min:15,
 en:["Turkey burger (no bun) with grilled vegetables",["1–2 turkey burgers (hamburguesa de pavo, ≈150 g)","1 courgette, ½ pepper, a few mushrooms","Lettuce leaves","1 tbsp olive oil","Salt, mustard"],["Slice the vegetables and grill them on a plancha with half the oil for 6–8 minutes.","Grill the burger 4 minutes per side.","Serve the burger on lettuce leaves instead of a bun, with mustard and the vegetables."]],
 es:["Hamburguesa de pavo sin pan con verduras a la plancha",["1–2 hamburguesas de pavo (≈150 g)","1 calabacín, ½ pimiento, unos champiñones","Hojas de lechuga","1 cucharada de aceite de oliva","Sal, mostaza"],["Corta las verduras en láminas y hazlas a la plancha con la mitad del aceite 6–8 minutos.","Haz la hamburguesa 4 minutos por cada lado.","Sírvela sobre hojas de lechuga en vez de pan, con mostaza y las verduras."]],
 ru:["Бургер из индейки (без булки) с овощами гриль",["1–2 котлеты из индейки (hamburguesa de pavo, ≈150 г)","1 кабачок, ½ перца, несколько шампиньонов","Листья салата","1 ст. ложка оливкового масла","Соль, горчица"],["Нарежь овощи пластинами и обжарь на plancha с половиной масла 6–8 минут.","Котлету жарь по 4 минуты с каждой стороны.","Подавай на листьях салата вместо булки, с горчицей и овощами."]],
 hy:["Հնդկահավի բուրգեր (առանց հացի) գրիլ բանջարեղենով",["1–2 հնդկահավի կոտլետ (hamburguesa de pavo, ≈150 գ)","1 դդմիկ, ½ պղպեղ, մի քանի սունկ","Հազարի տերևներ","1 ճաշի գդալ ձիթապտղի յուղ","Աղ, մանանեխ"],["Բանջարեղենը կտրատիր շերտերով և տապակիր plancha-ի վրա կես յուղով 6–8 րոպե։","Կոտլետը տապակիր 4 րոպե յուրաքանչյուր կողմից։","Մատուցիր հազարի տերևների վրա՝ հացի փոխարեն, մանանեխով և բանջարեղենով։"]]},
d11:{min:15,
 en:["Garlic prawns with courgette and mushrooms",["150 g frozen peeled prawns","1 courgette, 150 g mushrooms","2 garlic cloves","1 tbsp olive oil","Chili flakes, parsley, lemon, salt"],["Defrost the prawns in cold water for 5 minutes and dry them.","Sauté the diced courgette and sliced mushrooms in the oil for 6 minutes.","Add the garlic and chili for 1 minute, then the prawns for 2–3 minutes until pink.","Finish with parsley and lemon."]],
 es:["Gambas al ajillo con calabacín y champiñones",["150 g de gambas peladas congeladas","1 calabacín, 150 g de champiñones","2 dientes de ajo","1 cucharada de aceite de oliva","Guindilla, perejil, limón, sal"],["Descongela las gambas en agua fría 5 minutos y sécalas.","Saltea el calabacín en dados y los champiñones laminados en el aceite 6 minutos.","Añade el ajo y la guindilla 1 minuto y después las gambas 2–3 minutos, hasta que estén rosadas.","Termina con perejil y limón."]],
 ru:["Креветки с чесноком, кабачком и грибами",["150 г замороженных очищенных креветок","1 кабачок, 150 г шампиньонов","2 зубчика чеснока","1 ст. ложка оливкового масла","Хлопья чили, петрушка, лимон, соль"],["Разморозь креветки в холодной воде 5 минут и обсуши.","Обжарь кубики кабачка и пластинки грибов в масле 6 минут.","Добавь чеснок и чили на 1 минуту, затем креветки на 2–3 минуты, пока не порозовеют.","Посыпь петрушкой и сбрызни лимоном."]],
 hy:["Ծովախեցգետին սխտորով, դդմիկով և սնկով",["150 գ սառեցված մաքրած ծովախեցգետին","1 դդմիկ, 150 գ սունկ","2 պճեղ սխտոր","1 ճաշի գդալ ձիթապտղի յուղ","Չիլիի փաթիլ, մաղադանոս, կիտրոն, աղ"],["Ծովախեցգետինը հալեցրու սառը ջրում 5 րոպե և չորացրու։","Խորանարդիկ դդմիկն ու շերտերով սունկը տապակիր յուղով 6 րոպե։","Ավելացրու սխտորն ու չիլին 1 րոպեով, հետո ծովախեցգետինը 2–3 րոպե՝ մինչև վարդագույն դառնա։","Վրան՝ մաղադանոս և կիտրոն։"]]},
d12:{min:15,
 en:["Courgette omelette (tortilla de calabacín) with salad",["3 eggs","1 courgette","¼ onion","1 tbsp olive oil","Salt","Salad"],["Grate or thinly slice the courgette. Sauté it with the onion in half the oil for 6 minutes until soft.","Beat the eggs with salt and mix in the vegetables.","Pour into the pan with the rest of the oil. Cook 3 minutes, flip with a plate, 2 minutes more.","Serve with a salad."]],
 es:["Tortilla de calabacín con ensalada",["3 huevos","1 calabacín","¼ de cebolla","1 cucharada de aceite de oliva","Sal","Ensalada"],["Ralla o corta fino el calabacín. Sofríelo con la cebolla en la mitad del aceite 6 minutos, hasta que esté blando.","Bate los huevos con sal y mezcla con las verduras.","Echa en la sartén con el resto del aceite. Cocina 3 minutos, da la vuelta con un plato y 2 minutos más.","Sirve con ensalada."]],
 ru:["Омлет с кабачком (tortilla de calabacín) и салат",["3 яйца","1 кабачок","¼ луковицы","1 ст. ложка оливкового масла","Соль","Салат"],["Натри или тонко нарежь кабачок. Обжарь с луком в половине масла 6 минут до мягкости.","Взбей яйца с солью и смешай с овощами.","Вылей в сковороду с остатком масла. Готовь 3 минуты, переверни с помощью тарелки и ещё 2 минуты.","Подавай с салатом."]],
 hy:["Դդմիկով օմլետ (tortilla de calabacín) աղցանով",["3 ձու","1 դդմիկ","¼ սոխ","1 ճաշի գդալ ձիթապտղի յուղ","Աղ","Աղցան"],["Դդմիկը քերիր կամ բարակ կտրատիր։ Սոխի հետ տապակիր կես յուղով 6 րոպե՝ մինչև փափկի։","Ձվերը հարիր աղով և խառնիր բանջարեղենի հետ։","Լցրու տապակ մնացած յուղով։ Եփիր 3 րոպե, ափսեի օգնությամբ շուռ տուր և ևս 2 րոպե։","Մատուցիր աղցանով։"]]},
d13:{min:5,
 en:["No-cook plate: gazpacho, jamón and queso fresco",["1 glass (250 ml) gazpacho","50 g jamón serrano","100 g queso fresco (Burgos)","1 tomato","1 tsp olive oil, oregano","1 slice of bread (optional)"],["Pour the gazpacho into a glass.","Slice the tomato and the queso fresco; add the jamón.","Drizzle with the oil and oregano. Done — a summer dinner with no cooking."]],
 es:["Plato sin cocinar: gazpacho, jamón y queso fresco",["1 vaso (250 ml) de gazpacho","50 g de jamón serrano","100 g de queso fresco de Burgos","1 tomate","1 cucharadita de aceite de oliva, orégano","1 rebanada de pan (opcional)"],["Sirve el gazpacho en un vaso.","Corta el tomate y el queso fresco en rodajas; añade el jamón.","Riega con el aceite y el orégano. Listo: una cena de verano sin cocinar."]],
 ru:["Без готовки: гаспачо, хамон и свежий сыр",["1 стакан (250 мл) гаспачо","50 г хамона серрано","100 г свежего сыра (queso fresco de Burgos)","1 помидор","1 ч. л. оливкового масла, орегано","1 ломтик хлеба (по желанию)"],["Налей гаспачо в стакан.","Нарежь помидор и сыр ломтиками; добавь хамон.","Полей маслом и посыпь орегано. Готово — летний ужин без готовки."]],
 hy:["Առանց եփելու՝ գասպաչո, խամոն և թարմ պանիր",["1 բաժակ (250 մլ) գասպաչո","50 գ խամոն սերանո","100 գ թարմ պանիր (queso fresco de Burgos)","1 լոլիկ","1 թեյի գդալ ձիթապտղի յուղ, օրեգանո","1 շերտ հաց (ըստ ցանկության)"],["Գասպաչոն լցրու բաժակի մեջ։","Լոլիկն ու պանիրը կտրատիր շերտերով, ավելացրու խամոնը։","Վրան լցրու յուղն ու օրեգանոն։ Պատրաստ է՝ ամառային ընթրիք առանց եփելու։"]]},
d14:{min:25,
 en:["Courgette cream soup with boiled eggs and jamón",["2 courgettes","½ onion, ½ small potato","1 tbsp olive oil","400 ml water or stock","2 eggs","30 g jamón serrano","Salt, pepper"],["Sauté the chopped onion in the oil for 3 minutes. Add the chopped courgettes, potato and water; simmer 15 minutes.","Blend until smooth and season.","Boil the eggs for 10 minutes, cool and peel.","Serve the soup with the halved eggs and jamón strips on top."]],
 es:["Crema de calabacín con huevo cocido y jamón",["2 calabacines","½ cebolla, ½ patata pequeña","1 cucharada de aceite de oliva","400 ml de agua o caldo","2 huevos","30 g de jamón serrano","Sal, pimienta"],["Sofríe la cebolla picada en el aceite 3 minutos. Añade el calabacín y la patata troceados y el agua; cocina 15 minutos.","Tritura hasta que quede fina y salpimienta.","Cuece los huevos 10 minutos, enfría y pela.","Sirve la crema con los huevos partidos y tiras de jamón por encima."]],
 ru:["Крем-суп из кабачка с варёными яйцами и хамоном",["2 кабачка","½ луковицы, ½ небольшой картофелины","1 ст. ложка оливкового масла","400 мл воды или бульона","2 яйца","30 г хамона серрано","Соль, перец"],["Обжарь рубленый лук в масле 3 минуты. Добавь нарезанные кабачки, картофель и воду; вари 15 минут.","Пробей блендером до однородности и приправь.","Свари яйца 10 минут, остуди и очисти.","Подавай суп с половинками яиц и полосками хамона сверху."]],
 hy:["Դդմիկի կրեմ-ապուր խաշած ձվով և խամոնով",["2 դդմիկ","½ սոխ, ½ փոքր կարտոֆիլ","1 ճաշի գդալ ձիթապտղի յուղ","400 մլ ջուր կամ արգանակ","2 ձու","30 գ խամոն սերանո","Աղ, պղպեղ"],["Մանրացրած սոխը տապակիր յուղով 3 րոպե։ Ավելացրու կտրատած դդմիկը, կարտոֆիլն ու ջուրը, եփիր 15 րոպե։","Բլենդերով տրորիր մինչև համասեռ դառնա, համեմիր։","Ձվերը եփիր 10 րոպե, սառեցրու և մաքրիր։","Ապուրը մատուցիր կիսած ձվերով և խամոնի շերտերով։"]]},
d15:{min:15,
 en:["Grilled hake with garlic spinach",["200 g hake fillets (fresh or defrosted)","200 g spinach","2 garlic cloves","1 tbsp olive oil","Lemon, salt"],["Dry the fish well and season.","Grill on a hot plancha with half the oil, 3–4 minutes per side.","In the same pan, fry the sliced garlic for 30 seconds, add the spinach and cook 2 minutes until wilted.","Serve with lemon."]],
 es:["Merluza a la plancha con espinacas al ajillo",["200 g de filetes de merluza (fresca o descongelada)","200 g de espinacas","2 dientes de ajo","1 cucharada de aceite de oliva","Limón, sal"],["Seca bien el pescado y sazónalo.","Hazlo en la plancha caliente con la mitad del aceite, 3–4 minutos por lado.","En la misma sartén, dora el ajo laminado 30 segundos, añade las espinacas y cocina 2 minutos hasta que se ablanden.","Sirve con limón."]],
 ru:["Хек на гриле со шпинатом и чесноком",["200 г филе хека (свежего или размороженного)","200 г шпината","2 зубчика чеснока","1 ст. ложка оливкового масла","Лимон, соль"],["Хорошо обсуши рыбу и приправь.","Жарь на горячей plancha с половиной масла по 3–4 минуты с каждой стороны.","На той же сковороде обжарь нарезанный чеснок 30 секунд, добавь шпинат и готовь 2 минуты, пока не опадёт.","Подавай с лимоном."]],
 hy:["Գրիլ հեյք սխտորով սպանախի հետ",["200 գ հեյքի ֆիլե (թարմ կամ հալեցրած)","200 գ սպանախ","2 պճեղ սխտոր","1 ճաշի գդալ ձիթապտղի յուղ","Կիտրոն, աղ"],["Ձուկը լավ չորացրու և համեմիր։","Տապակիր տաք plancha-ի վրա կես յուղով, 3–4 րոպե յուրաքանչյուր կողմից։","Նույն տապակում 30 վայրկյան տապակիր կտրատած սխտորը, ավելացրու սպանախը և եփիր 2 րոպե՝ մինչև թառամի։","Մատուցիր կիտրոնով։"]]},
d16:{min:5,
 en:["Tomato, queso fresco and tuna salad",["2 tomatoes","100 g queso fresco (Burgos)","1 can of tuna in water","¼ red onion, 6 olives","1 tbsp olive oil, vinegar","Oregano, salt"],["Slice the tomatoes and the cheese.","Add the drained tuna, sliced onion and olives.","Dress with oil, vinegar, oregano and salt."]],
 es:["Ensalada de tomate, queso fresco y atún",["2 tomates","100 g de queso fresco de Burgos","1 lata de atún al natural","¼ de cebolla morada, 6 aceitunas","1 cucharada de aceite de oliva, vinagre","Orégano, sal"],["Corta los tomates y el queso en rodajas.","Añade el atún escurrido, la cebolla en tiras y las aceitunas.","Aliña con aceite, vinagre, orégano y sal."]],
 ru:["Салат с помидорами, свежим сыром и тунцом",["2 помидора","100 г свежего сыра (queso fresco de Burgos)","1 банка тунца в собственном соку","¼ красной луковицы, 6 оливок","1 ст. ложка оливкового масла, уксус","Орегано, соль"],["Нарежь помидоры и сыр ломтиками.","Добавь тунец без жидкости, нарезанный лук и оливки.","Заправь маслом, уксусом, орегано и солью."]],
 hy:["Լոլիկի, թարմ պանրի և տունայի աղցան",["2 լոլիկ","100 գ թարմ պանիր (queso fresco de Burgos)","1 բանկա տունա սեփական հյութում","¼ կարմիր սոխ, 6 ձիթապտուղ","1 ճաշի գդալ ձիթապտղի յուղ, քացախ","Օրեգանո, աղ"],["Լոլիկն ու պանիրը կտրատիր շերտերով։","Ավելացրու քամած տունան, կտրատած սոխն ու ձիթապտուղը։","Համեմիր յուղով, քացախով, օրեգանոյով և աղով։"]]},
d17:{min:10,
 en:["Spinach omelette with salad",["3 eggs","2 big handfuls of spinach","1 garlic clove","1 tsp olive oil","Salt","Salad"],["Wilt the spinach with the garlic in the oil for 2 minutes. Squeeze out the extra water.","Beat the eggs with salt and mix in the spinach.","Cook the omelette 2–3 minutes per side.","Serve with a salad."]],
 es:["Tortilla de espinacas con ensalada",["3 huevos","2 puñados grandes de espinacas","1 diente de ajo","1 cucharadita de aceite de oliva","Sal","Ensalada"],["Rehoga las espinacas con el ajo en el aceite 2 minutos. Escurre el agua que suelten.","Bate los huevos con sal y mezcla con las espinacas.","Cuaja la tortilla 2–3 minutos por cada lado.","Sirve con ensalada."]],
 ru:["Омлет со шпинатом и салат",["3 яйца","2 большие горсти шпината","1 зубчик чеснока","1 ч. л. оливкового масла","Соль","Салат"],["Потуши шпинат с чесноком в масле 2 минуты. Отожми лишнюю воду.","Взбей яйца с солью и смешай со шпинатом.","Готовь омлет по 2–3 минуты с каждой стороны.","Подавай с салатом."]],
 hy:["Սպանախով օմլետ աղցանով",["3 ձու","2 մեծ բուռ սպանախ","1 պճեղ սխտոր","1 թեյի գդալ ձիթապտղի յուղ","Աղ","Աղցան"],["Սպանախը սխտորի հետ թառամեցրու յուղով 2 րոպե։ Քամիր ավելորդ ջուրը։","Ձվերը հարիր աղով և խառնիր սպանախի հետ։","Օմլետը եփիր 2–3 րոպե յուրաքանչյուր կողմից։","Մատուցիր աղցանով։"]]},
d18:{min:15,
 en:["Steamed mussels with tomato and garlic",["500 g mussels (mejillones), cleaned","1 grated tomato","2 garlic cloves, ½ onion","1 tbsp olive oil","50 ml white wine or water","Parsley, lemon","Salad"],["Rinse the mussels and throw away any that stay open when tapped.","Sauté the chopped onion and garlic in the oil for 3 minutes; add the tomato for 2 more.","Add the mussels and the wine, cover and cook 5 minutes until they open. Discard any that stay closed.","Sprinkle with parsley and lemon. Serve with a salad."]],
 es:["Mejillones al vapor con tomate y ajo",["500 g de mejillones limpios","1 tomate rallado","2 dientes de ajo, ½ cebolla","1 cucharada de aceite de oliva","50 ml de vino blanco o agua","Perejil, limón","Ensalada"],["Lava los mejillones y desecha los que sigan abiertos al golpearlos.","Sofríe la cebolla y el ajo picados en el aceite 3 minutos; añade el tomate 2 minutos más.","Añade los mejillones y el vino, tapa y cocina 5 minutos hasta que se abran. Desecha los que queden cerrados.","Espolvorea perejil y limón. Sirve con ensalada."]],
 ru:["Мидии на пару с помидором и чесноком",["500 г мидий (mejillones), очищенных","1 тёртый помидор","2 зубчика чеснока, ½ луковицы","1 ст. ложка оливкового масла","50 мл белого вина или воды","Петрушка, лимон","Салат"],["Промой мидии и выброси те, что остаются открытыми при постукивании.","Обжарь рубленые лук и чеснок в масле 3 минуты; добавь помидор ещё на 2 минуты.","Добавь мидии и вино, накрой и готовь 5 минут, пока не раскроются. Нераскрывшиеся выброси.","Посыпь петрушкой, сбрызни лимоном. Подавай с салатом."]],
 hy:["Գոլորշիով եփած միդիաներ լոլիկով և սխտորով",["500 գ միդիա (mejillones), մաքրած","1 քերած լոլիկ","2 պճեղ սխտոր, ½ սոխ","1 ճաշի գդալ ձիթապտղի յուղ","50 մլ սպիտակ գինի կամ ջուր","Մաղադանոս, կիտրոն","Աղցան"],["Լվա միդիաները և դեն գցիր նրանք, որոնք թակելիս բաց են մնում։","Մանրացրած սոխն ու սխտորը տապակիր յուղով 3 րոպե, ավելացրու լոլիկը ևս 2 րոպեով։","Ավելացրու միդիաներն ու գինին, ծածկիր և եփիր 5 րոպե՝ մինչև բացվեն։ Փակ մնացածները դեն գցիր։","Վրան՝ մաղադանոս և կիտրոն։ Մատուցիր աղցանով։"]]},
d19:{min:25,
 en:["Chicken and vegetable soup",["150 g chicken breast (or leftover chicken)","1 carrot, 1 leek, ½ courgette","1 garlic clove","1 tsp olive oil","600 ml water + 1 stock cube","Salt, pepper"],["Sauté the sliced leek and carrot in the oil for 4 minutes.","Add the water, stock cube and the chicken. Simmer 15 minutes.","Take out the chicken, shred it and put it back. Add the diced courgette for the last 5 minutes.","Season and serve hot."]],
 es:["Sopa de pollo con verduras",["150 g de pechuga de pollo (o pollo sobrante)","1 zanahoria, 1 puerro, ½ calabacín","1 diente de ajo","1 cucharadita de aceite de oliva","600 ml de agua + 1 pastilla de caldo","Sal, pimienta"],["Sofríe el puerro y la zanahoria en rodajas con el aceite 4 minutos.","Añade el agua, la pastilla de caldo y el pollo. Cocina 15 minutos.","Saca el pollo, desmenúzalo y devuélvelo a la olla. Añade el calabacín en dados los últimos 5 minutos.","Salpimienta y sirve caliente."]],
 ru:["Куриный суп с овощами",["150 г куриной грудки (или оставшейся курицы)","1 морковь, 1 лук-порей, ½ кабачка","1 зубчик чеснока","1 ч. л. оливкового масла","600 мл воды + 1 бульонный кубик","Соль, перец"],["Обжарь нарезанные порей и морковь в масле 4 минуты.","Добавь воду, кубик и курицу. Вари 15 минут.","Вынь курицу, разбери на волокна и верни в кастрюлю. За 5 минут до конца добавь кубики кабачка.","Приправь и подавай горячим."]],
 hy:["Հավի ապուր բանջարեղենով",["150 գ հավի կրծքամիս (կամ մնացած հավ)","1 գազար, 1 պրաս, ½ դդմիկ","1 պճեղ սխտոր","1 թեյի գդալ ձիթապտղի յուղ","600 մլ ջուր + 1 արգանակի խորանարդ","Աղ, պղպեղ"],["Կտրատած պրասն ու գազարը տապակիր յուղով 4 րոպե։","Ավելացրու ջուրը, արգանակի խորանարդն ու հավը։ Եփիր 15 րոպե։","Հանիր հավը, թելերի բաժանիր և վերադարձրու կաթսա։ Վերջին 5 րոպեին ավելացրու խորանարդիկ դդմիկը։","Համեմիր և մատուցիր տաք։"]]},
d20:{min:0,kind:"guide",
 en:["Pizza or burger night: how to order",["Thin-crust pizza: half a pizza (3–4 slices) + a big salad","Burger: one patty, normal bun, no cheese sauce or bacon","Side: salad instead of fries","Drink: water or Coke Zero","Skip: garlic bread, nachos, stuffed crust, double patties"],["Order a salad first and eat it before the main.","Share a pizza: half for you. Or a single burger with a salad side instead of fries.","Say no to the starters and the stuffed crust.","Drink water or a zero drink. If you want alcohol, one beer counts toward your 1–2 a week.","Dessert: a coffee. You still lose weight this week if the rest of the days are on plan."]],
 es:["Noche de pizza o hamburguesa: cómo pedir",["Pizza de masa fina: media pizza (3–4 porciones) + ensalada grande","Hamburguesa: una carne, pan normal, sin salsa de queso ni bacon","Acompañamiento: ensalada en vez de patatas","Bebida: agua o Coca-Cola Zero","Evita: pan de ajo, nachos, bordes rellenos, doble carne"],["Pide primero una ensalada y cómetela antes del plato principal.","Comparte una pizza: la mitad para ti. O una hamburguesa sencilla con ensalada en vez de patatas.","Di que no a los entrantes y a los bordes rellenos.","Bebe agua o un refresco zero. Si quieres alcohol, una cerveza cuenta para tus 1–2 de la semana.","De postre, un café. Esta semana sigues perdiendo peso si el resto de días cumples el plan."]],
 ru:["Вечер пиццы или бургера: что заказывать",["Пицца на тонком тесте: половина пиццы (3–4 куска) + большой салат","Бургер: одна котлета, обычная булка, без сырного соуса и бекона","Гарнир: салат вместо картошки фри","Напиток: вода или Coca-Cola Zero","Не брать: чесночный хлеб, начос, сырный бортик, двойную котлету"],["Сначала закажи салат и съешь его до основного блюда.","Пиццу — на двоих: половина тебе. Или один бургер с салатом вместо фри.","Откажись от закусок и сырного бортика.","Пей воду или «зеро». Если хочешь алкоголь — одно пиво входит в твои 1–2 в неделю.","Десерт — кофе. Ты всё равно худеешь на этой неделе, если остальные дни по плану."]],
 hy:["Պիցցայի կամ բուրգերի երեկո. ինչ պատվիրել",["Բարակ խմորով պիցցա՝ կես պիցցա (3–4 կտոր) + մեծ աղցան","Բուրգեր՝ մեկ կոտլետ, սովորական հաց, առանց պանրի սոուսի և բեկոնի","Կողքին՝ աղցան՝ կարտոֆիլ ֆրիի փոխարեն","Ըմպելիք՝ ջուր կամ Coca-Cola Zero","Մի պատվիրիր՝ սխտորով հաց, նաչոս, պանրով եզրեր, կրկնակի կոտլետ"],["Սկզբում պատվիրիր աղցան և կեր այն հիմնական ուտեստից առաջ։","Պիցցան կիսիր՝ կեսը քեզ։ Կամ մեկ պարզ բուրգեր՝ աղցանով՝ կարտոֆիլ ֆրիի փոխարեն։","Հրաժարվիր նախուտեստներից և պանրով եզրերից։","Խմիր ջուր կամ zero ըմպելիք։ Եթե ալկոհոլ ես ուզում, մեկ գարեջուրը մտնում է քո շաբաթական 1–2-ի մեջ։","Աղանդեր՝ սուրճ։ Այս շաբաթ էլ կնիհարես, եթե մնացած օրերը պլանով են։"]]},
d21:{min:10,
 en:["Gambas al ajillo (light) with salad",["200 g frozen peeled prawns","3 garlic cloves","1 tbsp olive oil","1 dried chili (guindilla)","Parsley, lemon, salt","A big salad"],["Defrost the prawns in cold water for 5 minutes and dry them well.","Heat the oil with the sliced garlic and chili over low heat for 2 minutes — don't let the garlic burn.","Turn the heat up, add the prawns and cook 2–3 minutes until pink.","Parsley, lemon, salt. Serve with a big salad; bread: one slice at most."]],
 es:["Gambas al ajillo (ligeras) con ensalada",["200 g de gambas peladas congeladas","3 dientes de ajo","1 cucharada de aceite de oliva","1 guindilla","Perejil, limón, sal","Una ensalada grande"],["Descongela las gambas en agua fría 5 minutos y sécalas bien.","Calienta el aceite con el ajo laminado y la guindilla a fuego suave 2 minutos, sin que el ajo se queme.","Sube el fuego, añade las gambas y cocina 2–3 minutos hasta que estén rosadas.","Perejil, limón y sal. Sirve con una ensalada grande; pan: una rebanada como máximo."]],
 ru:["Гамбас аль ахильо (лёгкие) с салатом",["200 г замороженных очищенных креветок","3 зубчика чеснока","1 ст. ложка оливкового масла","1 сушёный перчик чили (guindilla)","Петрушка, лимон, соль","Большой салат"],["Разморозь креветки в холодной воде 5 минут и хорошо обсуши.","Разогрей масло с нарезанным чесноком и чили на слабом огне 2 минуты — чеснок не должен подгореть.","Прибавь огонь, добавь креветки и готовь 2–3 минуты, пока не порозовеют.","Петрушка, лимон, соль. Подавай с большим салатом; хлеб — максимум один ломтик."]],
 hy:["Gambas al ajillo (թեթև) աղցանով",["200 գ սառեցված մաքրած ծովախեցգետին","3 պճեղ սխտոր","1 ճաշի գդալ ձիթապտղի յուղ","1 չոր չիլի (guindilla)","Մաղադանոս, կիտրոն, աղ","Մեծ աղցան"],["Ծովախեցգետինը հալեցրու սառը ջրում 5 րոպե և լավ չորացրու։","Յուղը կտրատած սխտորի և չիլիի հետ տաքացրու թույլ կրակի վրա 2 րոպե՝ սխտորը չպետք է այրվի։","Ուժեղացրու կրակը, ավելացրու ծովախեցգետինը և եփիր 2–3 րոպե՝ մինչև վարդագույն դառնա։","Մաղադանոս, կիտրոն, աղ։ Մատուցիր մեծ աղցանով, հաց՝ առավելագույնը մեկ շերտ։"]]}
});
